admin.messaging().send({
  token: deviceToken,
  data: {
    type: 'order_update',
    orderId: '12345',
    status: 'shipped',
    screen: 'order_detail',
  },
  notification: {
    title: 'Ваш заказ отправлен',
    body: 'Заказ #12345 передан в службу доставки',
  },
});
